import collections
import os
import sys

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402
import p1v4_grounding as G  # noqa: E402
import p1v4_reliability_fix as FIX  # noqa: E402
import p1v4_reliability_fix3 as F3  # noqa: E402


def since_last(r, t, cls):
    s = sorted(x["start"] for x in r["sources"] if x["kind"] == "clip" and x.get("cls") == cls and x["start"] < t)
    return t - s[-1] if s else None


def merged(r, t, cls):
    xs = sorted((s["start"], s["end"]) for s in r["sources"]
                if s["kind"] == "clip" and s.get("cls") == cls and s["start"] < t)
    m = []
    for a, b in xs:
        if m and a - m[-1][1] < F3.MERGE_S:
            m[-1][1] = max(m[-1][1], b)
        else:
            m.append([a, b])
    return m


def relation(r, w):
    line = next((s for s in r["sources"] if s["kind"] == "speech" and s["id"] == w["line"]), None)
    out = []
    for cls in ("phone", "doorbell"):
        for a, b in merged(r, w["t"], cls):
            if line is None:
                rel = "no line"
            elif b <= line["start"]:
                rel = "ended before the line, gap " + ("<=3s" if line["start"] - b <= 3 else ">3s")
            elif a >= line["start"]:
                rel = "started during or after the line"
            else:
                rel = "still on when the line started"
            out.append((cls, rel))
    return out


def relation_table(rows_by, wins, name):
    tab = collections.Counter()
    for w in wins:
        g = w["gold"].get("R")
        if g is None:
            continue
        for cls, rel in relation(rows_by[(w["unit"], w["version"])], w):
            tab[(cls, rel, g)] += 1
    print(name)
    for c, r in sorted({(c, r) for c, r, _ in tab}):
        n1, n0 = tab[(c, r, "respond")], tab[(c, r, "not")]
        print(f"   {c:8s} {r:40s} n {n1 + n0:6d}  respond {n1 / (n1 + n0):.3f}")


def main():
    rows, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    keys = {(g["unit"], v, g["k"]) for g in groups for v in g["versions"]}
    gw = [w for w in D.windows_of(rows, "dev") if (w["unit"], w["version"], w["k"]) in keys]
    gof = {g["unit"]: g for g in groups}
    cov = {g["unit"]: F3.covered(g, rows_by) for g in groups}
    print("1. dev covered groups")
    for part, q in (("r_hear", "R"), ("s_move", "S")):
        rec = []
        for w in gw:
            if gof[w["unit"]]["part"] != part or not cov[w["unit"]] or w["gold"].get(q) is None:
                continue
            r = rows_by[(w["unit"], w["version"])]
            dts = [x for x in (since_last(r, w["t"], c) for c in F3.COVER) if x is not None]
            pos = int(w["gold"][q] == ("respond" if q == "R" else "stop"))
            rec.append((w["version"], min(dts) if dts else None, pos))
        dd = [x[1] for x in rec if x[1] is not None]
        print(f"   {part}: {len(dd)} of {len(rec)} questions with a notification; seconds since it: "
              f"min {min(dd):.1f}, median {np.median(dd):.1f}, max {max(dd):.1f}")
        print("   (version, notification, positive answer) counts:",
              dict(sorted(collections.Counter((v, d is not None, p) for v, d, p in rec).items())))
        for W in (3, 5, 10, None):
            right = 0
            for _, d, p in rec:
                recent = d is not None and (W is None or d <= W)
                right += ((0 if recent else 1) if q == "R" else (1 if recent else 0)) == p
            print(f"   notification-only rule, window {W if W else 'any'} s: accuracy {right / len(rec):.3f}")
    print("\n2. train windows with the service on: positive answer by covered class and seconds since its last notification")
    on = F3.load_assign3()
    trows, twins = FIX.train_rows()
    tby = {(r["unit"], r["version"]): r for r in trows}
    cnt = collections.Counter()
    for w in twins:
        if not on[w["unit"]]:
            continue
        r = tby[w["key"]]
        for q in ("S", "R"):
            g = w["gold"].get(q)
            if g is None:
                continue
            pos = int(g == ("respond" if q == "R" else "stop"))
            for cls in F3.COVER:
                d = since_last(r, w["t"], cls)
                b = "none" if d is None else ("<=5s" if d <= 5 else ("5-15s" if d <= 15 else ">15s"))
                cnt[(q, cls, b, pos)] += 1
    for q in ("R", "S"):
        for cls in F3.COVER:
            for b in ("<=5s", "5-15s", ">15s", "none"):
                n1, n0 = cnt[(q, cls, b, 1)], cnt[(q, cls, b, 0)]
                if n1 + n0:
                    print(f"   {q} {cls:8s} {b:6s} n {n1 + n0:6d}  positive {n1 / (n1 + n0):.3f}")
    print("\n3. R questions after a phone or doorbell, by the ring's timing relative to the line")
    relation_table(tby, twins, "   train:")
    relation_table(rows_by, D.windows_of(rows, "dev"), "   natural dev:")
    relation_table(rows_by, [w for w in gw if gof[w["unit"]]["part"] == "r_hear"], "   dev r_hear groups:")
    print("\n4. train R questions after a phone ring that ended <= 3 s before the line: do the words separate the answers?")
    txt = collections.defaultdict(collections.Counter)
    for w in twins:
        g = w["gold"].get("R")
        r = tby[w["key"]]
        if g is None or not any(c == "phone" and x.startswith("ended before the line, gap <=3s") for c, x in relation(r, w)):
            continue
        line = next((s for s in r["sources"] if s["kind"] == "speech" and s["id"] == w["line"]), None)
        if line is not None:
            txt[g][line.get("text", "")] += 1
    for g in ("not", "respond"):
        print(f"   {g}: n {sum(txt[g].values())}, distinct lines {len(txt[g])}, most common:",
              [(t[:40], n) for t, n in txt[g].most_common(5)])
    print("   distinct lines that occur with both answers:", len(set(txt["not"]) & set(txt["respond"])))


if __name__ == "__main__":
    main()
